public record Money(BigDecimal amount, Currency currency) {
    public Money {
        Objects.requireNonNull(amount);
        Objects.requireNonNull(currency);
        if (amount.signum() < 0) {
            throw new IllegalArgumentException("Money amount cannot be negative");
        }
    }

    public Money add(Money other) {
        if (!this.currency.equals(other.currency)) {
            throw new IllegalArgumentException("Currency mismatch");
        }
        return new Money(this.amount.add(other.amount), this.currency);
    }
}

public class OrderId {
    private final UUID id;
    public OrderId(UUID id) { this.id = Objects.requireNonNull(id); }
    // equals and hashCode implementation based strictly on id
}

public class Order {
    private final OrderId id;
    private OrderStatus status;
    private final List<OrderItem> items = new ArrayList<>();

    public void addLineItem(Product product, int quantity, Money price) {
        if (this.status != OrderStatus.DRAFT) {
            throw new IllegalStateException(
                "Cannot modify an order that has already been submitted."
            );
        }
        this.items.add(new OrderItem(product, quantity, price));
    }
}
